import {api,escapeHtml as esc} from './catalog.js';
import {loadSession,isAdmin} from './access.js';
import {adminNav} from './multimedia.js';
const root=document.querySelector('#users-panel');let users=[];
async function render(){const {items}=await api('/users');users=items;root.innerHTML=adminNav+`<div class="feature-intro"><h2>Những người cùng Nét.</h2><p>Tạo tài khoản, phân quyền và quản lý trạng thái hoạt động.</p></div><button class="button button-dark" id="add-user">+ Thêm người dùng</button><p id="users-error" class="form-error" role="alert"></p><div class="table-scroll"><table class="feature-table"><thead><tr><th>Họ tên / email</th><th>Tài khoản</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}<br><small>Mã: ${esc(u.id)}</small><br><small>${esc(u.email)}</small></td><td>${esc(u.username)}</td><td>${u.role==='admin'?'Quản trị viên':'Người dùng'}</td><td>${u.active?'Hoạt động':'Đã khóa'}</td><td><button class="text-link" data-edit="${esc(u.id)}">Sửa</button> <button class="danger-link" data-delete="${esc(u.id)}">Xóa</button></td></tr>`).join('')}</tbody></table></div><dialog id="user-dialog" class="management-dialog" aria-labelledby="user-title"><div class="dialog-heading"><h2 id="user-title"></h2><button type="button" data-close aria-label="Đóng">×</button></div><form id="user-form" class="user-form"></form></dialog>`;root.querySelector('#add-user').onclick=()=>edit();root.querySelector('[data-close]').onclick=()=>root.querySelector('dialog').close();}
function edit(u){const form=root.querySelector('#user-form');root.querySelector('#user-title').textContent=u?'Chỉnh sửa người dùng':'Thêm người dùng';form.innerHTML=`<label>Họ và tên<input name="name" maxlength="150" required value="${esc(u?.name||'')}"></label><label>Email<input name="email" type="email" required value="${esc(u?.email||'')}" ${u?'disabled':''}></label><label>Tên tài khoản<input name="username" required maxlength="80" value="${esc(u?.username||'')}"><small>Từ 3–80 ký tự: chữ thường, số, dấu chấm, gạch nối hoặc gạch dưới.</small></label><label>Vai trò<select name="role"><option value="user" ${u?.role!=='admin'?'selected':''}>Người dùng</option><option value="admin" ${u?.role==='admin'?'selected':''}>Quản trị viên</option></select></label>${u?`<label>Trạng thái<select name="active"><option value="true" ${u.active?'selected':''}>Hoạt động</option><option value="false" ${!u.active?'selected':''}>Khóa tài khoản</option></select></label>`:''}<label>${u?'Mật khẩu mới (bỏ trống để giữ nguyên)':'Mật khẩu'}<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="200" ${u?'':'required'}></label><p class="form-error" role="alert" id="user-error"></p><button class="button button-dark">Lưu tài khoản ↗</button>`;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(u)data.active=data.active==='true';await api(u?'/users/'+u.id:'/users',{method:u?'PUT':'POST',body:JSON.stringify(data)});root.querySelector('dialog').close();const session=await loadSession({refresh:true});if(!isAdmin(session.user)){location.assign('/tai-khoan/');return;}await render();}catch(error){form.querySelector('#user-error').textContent=error.message;}finally{button.disabled=false;}};root.querySelector('dialog').showModal();}
root.addEventListener('click',async e=>{const editButton=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(editButton)edit(users.find(u=>u.id===editButton.dataset.edit));if(del&&confirm('Xóa tài khoản này? Các phiên đăng nhập và mục đã lưu của tài khoản sẽ bị xóa.'))try{await api('/users/'+del.dataset.delete,{method:'DELETE'});await render();}catch(error){root.querySelector('#users-error').textContent=error.message;}});
try{const session=await loadSession();if(!isAdmin(session.user))root.innerHTML='<p>Chức năng dành cho quản trị viên.</p><a href="/tai-khoan/">Đăng nhập ↗</a>';else await render();}catch(error){root.textContent=error.message;}
